CREATE TABLE t3(a,b,c); WITH s(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM s WHERE i<6) INSERT INTO t3 SELECT i,i,i FROM s; CREATE VIEW v1 AS SELECT sum(b) OVER (ORDER BY c), min(b) OVER (ORDER BY c), max(b) OVER (ORDER BY c) FROM t3; CREATE VIEW v2 AS SELECT sum(b) OVER win, min(b) OVER win, max(b) OVER win FROM t3 WINDOW win AS (ORDER BY c);